import React, { useState } from 'react';
import axios from 'axios';
import '../styles/Login.css';

const Register = () => {
  const [role, setRole] = useState('');
  const [isEntreprise, setIsEntreprise] = useState(false);
  const [formData, setFormData] = useState({
    nom: '',
    prenom: '',
    email: '',
    mot_de_passe: '',
    telephone: '',
    numero_tva: '',
    adresse: '',
    ville: '',
    code_postal: '',
    type_client: 'particulier'
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (!formData.adresse || !formData.ville || !formData.code_postal) {
      setError('L\'adresse complète est obligatoire');
      setLoading(false);
      return;
    }

    try {
      const response = await axios.post('http://localhost:8000/api/auth/register', {
        ...formData,
        role: role
      });
      localStorage.setItem('token', response.data.token);
      localStorage.setItem('user', JSON.stringify(response.data.data));
      window.location.href = '/dashboard';
    } catch (err) {
      setError(err.response?.data?.message || 'Erreur lors de l\'inscription');
    } finally {
      setLoading(false);
    }
  };

  // Écran de choix du rôle
  if (!role) {
    return (
      <div className="login-container">
        <div className="login-box" style={{ maxWidth: '500px' }}>
          <h1>🏗️ Système OMC</h1>
          <h2>Créer un compte</h2>
          <p style={{ color: '#666', marginBottom: '30px' }}>Choisissez votre type de compte :</p>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
            <button
              onClick={() => setRole('client')}
              style={{
                padding: '25px',
                border: '2px solid #4caf50',
                borderRadius: '12px',
                background: '#e8f5e9',
                cursor: 'pointer',
                textAlign: 'left'
              }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                <span style={{ fontSize: '40px' }}>👤</span>
                <div>
                  <h3 style={{ margin: '0 0 5px 0', color: '#2e7d32' }}>Je suis un Client</h3>
                  <p style={{ margin: 0, color: '#666', fontSize: '14px' }}>
                    Je veux consulter mes devis et factures
                  </p>
                </div>
              </div>
            </button>

            <button
              onClick={() => setRole('admin')}
              style={{
                padding: '25px',
                border: '2px solid #667eea',
                borderRadius: '12px',
                background: '#e3f2fd',
                cursor: 'pointer',
                textAlign: 'left'
              }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                <span style={{ fontSize: '40px' }}>🔧</span>
                <div>
                  <h3 style={{ margin: '0 0 5px 0', color: '#1565c0' }}>Je suis Administrateur</h3>
                  <p style={{ margin: 0, color: '#666', fontSize: '14px' }}>
                    Je gère les devis et factures des clients
                  </p>
                </div>
              </div>
            </button>
          </div>

          <p className="register-link" style={{ marginTop: '30px' }}>
            Déjà un compte ? <a href="/login">Se connecter</a>
          </p>
        </div>
      </div>
    );
  }

  // Formulaire d'inscription
  return (
    <div className="login-container">
      <div className="login-box" style={{ maxWidth: '550px' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '20px' }}>
          <h1 style={{ margin: 0 }}>🏗️ Système OMC</h1>
          <span style={{
            padding: '5px 15px',
            borderRadius: '20px',
            fontSize: '14px',
            fontWeight: 'bold',
            background: role === 'admin' ? '#667eea' : '#4caf50',
            color: 'white'
          }}>
            {role === 'admin' ? '🔧 Admin' : '👤 Client'}
          </span>
        </div>
        <h2>Créer mon compte {role === 'admin' ? 'Administrateur' : 'Client'}</h2>

        <button 
          onClick={() => setRole('')}
          style={{ marginBottom: '20px', padding: '8px 15px', background: '#f5f5f5', border: '1px solid #ddd', borderRadius: '6px', cursor: 'pointer' }}
        >
          ← Changer de type de compte
        </button>

        {error && <div className="error-message">{error}</div>}

        {role === 'client' && (
          <div style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
            <button 
              type="button"
              onClick={() => { setIsEntreprise(false); setFormData({ ...formData, type_client: 'particulier', numero_tva: '' }); }}
              style={{
                flex: 1, padding: '12px', 
                border: '2px solid', borderColor: !isEntreprise ? '#667eea' : '#ddd',
                background: !isEntreprise ? '#667eea' : 'white',
                color: !isEntreprise ? 'white' : '#333',
                borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold'
              }}
            >
              👤 Particulier
            </button>
            <button 
              type="button"
              onClick={() => { setIsEntreprise(true); setFormData({ ...formData, type_client: 'professionnel' }); }}
              style={{
                flex: 1, padding: '12px', 
                border: '2px solid', borderColor: isEntreprise ? '#667eea' : '#ddd',
                background: isEntreprise ? '#667eea' : 'white',
                color: isEntreprise ? 'white' : '#333',
                borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold'
              }}
            >
              🏢 Entreprise
            </button>
          </div>
        )}

        <form onSubmit={handleSubmit}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
            <div className="form-group">
              <label>{isEntreprise ? 'Nom société *' : 'Nom *'}</label>
              <input type="text" name="nom" value={formData.nom} onChange={handleChange} required />
            </div>
            <div className="form-group">
              <label>{isEntreprise ? 'Personne de contact' : 'Prénom *'}</label>
              <input type="text" name="prenom" value={formData.prenom} onChange={handleChange} required={!isEntreprise} />
            </div>
          </div>

          <div className="form-group">
            <label>Email *</label>
            <input type="email" name="email" value={formData.email} onChange={handleChange} required />
          </div>

          <div className="form-group">
            <label>Mot de passe *</label>
            <input type="password" name="mot_de_passe" value={formData.mot_de_passe} onChange={handleChange} required minLength="6" />
          </div>

          <div className="form-group">
            <label>Téléphone *</label>
            <input type="tel" name="telephone" value={formData.telephone} onChange={handleChange} required placeholder="+32 xxx xx xx xx" />
          </div>

          {isEntreprise && (
            <div className="form-group">
              <label>Numéro de TVA (facultatif)</label>
              <input type="text" name="numero_tva" value={formData.numero_tva} onChange={handleChange} placeholder="BE0123456789" />
              <small style={{ color: '#666', fontSize: '12px' }}>Format: BE + 10 chiffres</small>
            </div>
          )}

          <div className="form-group">
            <label>Adresse *</label>
            <input type="text" name="adresse" value={formData.adresse} onChange={handleChange} required placeholder="Rue et numéro" />
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr', gap: '10px' }}>
            <div className="form-group">
              <label>Code postal *</label>
              <input type="text" name="code_postal" value={formData.code_postal} onChange={handleChange} required />
            </div>
            <div className="form-group">
              <label>Ville *</label>
              <input type="text" name="ville" value={formData.ville} onChange={handleChange} required />
            </div>
          </div>

          <button type="submit" disabled={loading} style={{ marginTop: '15px', width: '100%' }}>
            {loading ? 'Création en cours...' : 'Créer mon compte'}
          </button>
        </form>

        <p className="register-link">
          Déjà un compte ? <a href="/login">Se connecter</a>
        </p>
      </div>
    </div>
  );
};

export default Register;
